# ------------------------------------------------------------------ 2. SHM graphs and phase
_XT = dict(diagram="al-phl2-q-xt-graph.svg", diagram_alt="A sine-shaped graph of displacement x in centimetres against time t in seconds. It starts at zero, rises to 3 cm, falls through zero and reaches minus 3 cm, then returns to zero, and repeats. Gridlines are every 0.1 s and every 1 cm up to 0.8 s.")
