            steps=[S("Fringe spacing", math=r"w = \frac{\lambda D}{a} = \frac{5.0\times10^{-7} \times 2.0}{4.0\times10^{-4}} = 2.5\times10^{-3}\ \text{m} = 2.5\ \text{mm}")],
